const fs = require('fs');
const path = require('path');

const csvFilePath = '/data/samples/user_activity_sample.csv';
const mooseIngestUrl = 'http://localhost:4000/ingest/UserActivity';

// Read and parse CSV
function loadSampleData() {
    const csvContent = fs.readFileSync(csvFilePath, 'utf8');
    const lines = csvContent.trim().split('\n');
    const headers = lines[0].split(',');

    console.log('Headers:', headers);
    console.log(`Loading ${lines.length - 1} records...`);

    for (let i = 1; i < lines.length; i++) {
        const values = lines[i].split(',');

        // Skip empty lines
        if (values.length < headers.length) continue;

        const record = {
            event_id: values[0],
            event_ts: new Date(values[1]).toISOString(),
            user_id: values[2],
            action: values[3],
            duration_ms: values[4] ? parseFloat(values[4]) || 0 : 0
        };

        console.log(`Sending record ${i}:`, record);

        // Send to Moose ingestion API
        fetch(mooseIngestUrl, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify(record)
        })
        .then(response => {
            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }
            return response.text();
        })
        .then(data => {
            console.log(`✓ Record ${i} loaded successfully:`, data || 'OK');
        })
        .catch(error => {
            console.error(`✗ Error loading record ${i}:`, error);
        });
    }
}

loadSampleData();

